#include <iostream>
#include <iomanip>
#include <string>

// Base class representing a commission employee
class CommissionEmployee {
public:
    CommissionEmployee(std::string first, std::string last, std::string ssn,
                       double sales, double rate)
        : firstName{std::move(first)}, lastName{std::move(last)},
          socialSecurityNumber{std::move(ssn)},
          grossSales{sales}, commissionRate{rate} {}

    // Non-virtual print demonstrating compile-time handle dispatch
    void print() const {
        std::cout << "commission employee: " << firstName << ' ' << lastName
                  << "\nsocial security number: " << socialSecurityNumber
                  << "\ngross sales: " << grossSales
                  << "\ncommission rate: " << commissionRate;
    }

    double getGrossSales() const { return grossSales; }
    double getCommissionRate() const { return commissionRate; }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales{0.0};
    double commissionRate{0.0};
};

// Derived class extending with base salary
class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string first, std::string last, std::string ssn,
                               double sales, double rate, double salary)
        : CommissionEmployee{std::move(first), std::move(last), std::move(ssn), sales, rate},
          baseSalary{salary} {}

    // Redefined print (non-virtual)
    void print() const {
        CommissionEmployee::print();
        std::cout << "\nbase salary: " << baseSalary;
    }

    double getBaseSalary() const { return baseSalary; }

private:
    double baseSalary{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    CommissionEmployee commissionEmployee{"Sue", "Jones", "222-22-2222", 10000.0, 0.06};
    BasePlusCommissionEmployee basePlusCommissionEmployee{"Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0};

    CommissionEmployee* commissionEmployeePtr = nullptr;
    BasePlusCommissionEmployee* basePlusCommissionEmployeePtr = nullptr;

    // 1. Aim base pointer at base object
    commissionEmployeePtr = &commissionEmployee;
    std::cout << "Calling print via base-class pointer to base-class object:\n";
    commissionEmployeePtr->print();
    std::cout << "\n\n";

    // 2. Aim derived pointer at derived object
    basePlusCommissionEmployeePtr = &basePlusCommissionEmployee;
    std::cout << "Calling print via derived-class pointer to derived-class object:\n";
    basePlusCommissionEmployeePtr->print();
    std::cout << "\n\n";

    // 3. Aim base pointer at derived object (allowed due to is-a)
    commissionEmployeePtr = &basePlusCommissionEmployee;
    std::cout << "Calling print via base-class pointer to derived-class object:\n";
    // Non-virtual call dispatches according to handle type (CommissionEmployee)
    commissionEmployeePtr->print();
    std::cout << "\n";

    return 0;
}
